"""Original delirium questions: recognition, assessment and proportionate care."""
from qbank_authoring import question,ref
rows=[]
DL=ref('NICE delirium prevention, diagnosis and management','https://www.nice.org.uk/guidance/cg103/chapter/Recommendations')
DM=ref('NICE dementia assessment and management','https://www.nice.org.uk/guidance/ng97/chapter/Recommendations')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('An older inpatient develops fluctuating inattention and disorientation over 24 hours after surgery. Family reports a normal baseline. Which syndrome is most likely?', 'Delirium',[
 ('A new slowly progressive dementia as the sole explanation','The acute fluctuating course favors delirium.'),('Major depression alone','Depression does not usually produce this abrupt fluctuating attention/awareness pattern.'),('Primary schizophrenia','First-onset acute cognitive fluctuation after surgery requires a medical delirium assessment.')],
 'Time course and attention are central','**Delirium is an acute change in attention/awareness with additional cognitive disturbance.**',['Symptoms can fluctuate and may be missed during a brief lucid interval.','Hyperactive, hypoactive and mixed presentations occur.'],'**Search for causes while providing supportive care.**',['Review drugs, infection, oxygenation, pain and metabolic changes.','Obtain collateral baseline information.'],[['Onset','Hours to days'],['Course','Fluctuating'],['Core','Inattention/awareness change']],[DL],style='clinical_scenario')

q('Under NICE guidance, which brief tool is recommended for suspected delirium in a general hospital setting outside critical care?', '4AT',[
 ('PHQ-9','This is a depression screening/severity instrument.'),('AUDIT','This screens alcohol-related risk rather than diagnosing delirium.'),('A personality inventory','This is not a brief acute-confusion assessment.')],
 'Use a tool designed for the clinical task','**The 4AT supports rapid delirium assessment.**',['A positive result needs clinical interpretation and cause evaluation.','A tool does not replace baseline and time-course information.'],'**Use the recommended critical-care tools when appropriate instead.**',['CAM-ICU or ICDSC are appropriate in ICU/recovery contexts.','Reassess when symptoms fluctuate or suspicion persists.'],[['General setting','4AT'],['Critical care','CAM-ICU/ICDSC'],['All settings','Clinical interpretation']],[DL])

q('An intubated ICU patient can respond nonverbally. Which delirium-assessment approach is appropriate?', 'Use a validated ICU tool such as CAM-ICU with an arousal assessment',[
 ('Require spoken answers to every general cognitive question before any assessment','Validated nonverbal ICU assessments are available.'),('Assume intubation makes delirium impossible to assess','The airway tube does not eliminate assessment options.'),('Diagnose delirium from tachycardia alone','Autonomic signs are nonspecific.')],
 'Arousal determines whether attention can be assessed','**CAM-ICU was designed for critically ill patients including those unable to speak.**',['Deep unresponsiveness may make a delirium assessment temporarily untestable.','Sedation and illness can confound findings.'],'**Record the tool result and clinical context.**',['Use serial assessment and review sedative exposure.','Treat contributing causes rather than only the screening score.'],[['Arousal','Assess first'],['Communication','Nonverbal tools possible'],['Interpretation','Serial and context-based']],[DL],style='clinical_scenario')

q('A patient with known dementia becomes acutely less attentive and more disoriented during an infection. Which conclusion is appropriate?', 'Delirium superimposed on dementia should be assessed and treated',[
 ('Dementia excludes delirium','Baseline cognitive impairment increases rather than removes delirium risk.'),('All change is inevitable dementia progression','An acute change can reflect a reversible medical problem.'),('A normal previous cognitive score is required before delirium can be diagnosed','Collateral baseline and the acute change can establish the concern.')],
 'Baseline impairment does not explain every new deterioration','**Delirium and dementia commonly coexist.**',['Use family/carer observations of the usual state.','Treat delirium first when the distinction is uncertain.'],'**Investigate the precipitating illness and medication changes.**',['Reassess cognition after the acute syndrome resolves.','Support orientation, sensory needs and familiar contact.'],[['Baseline','Chronic impairment'],['New change','Acute fluctuating decline'],['Response','Treat delirium and reassess']],[DL,DM],style='clinical_scenario')

q('Which prevention plan is most appropriate for an older high-risk hospital patient?', 'A tailored multicomponent program addressing orientation, hydration, mobility, sleep, sensory aids and medical contributors',[
 ('Routine sedative medication for every patient to ensure sleep','Sedation can increase delirium and fall risks.'),('Routine prophylactic antipsychotics as the sole prevention strategy','This does not replace multicomponent prevention and is not routine care.'),('Bed rest and sensory isolation until discharge','These can worsen disorientation and deconditioning.')],
 'Preventing delirium requires several small physiological supports','**Modifiable contributors often coexist.**',['Pain, constipation, urinary retention and unnecessary catheters need attention.','Glasses, hearing aids and clear communication improve orientation.'],'**Adapt the bundle to the individual and reassess daily.**',['Avoid unnecessary transfers and medication burden.','Encourage safe mobility and family involvement.'],[['Orientation/senses','Communication and aids'],['Physiology','Hydration, pain and medical care'],['Function','Sleep and mobility']],[DL])

q('A patient develops delirium after starting oxybutynin while already taking sedating antihistamines. Which mechanism is especially relevant?', 'Cumulative anticholinergic medication burden',[
 ('A required new structural brain lesion','Medication-related delirium is plausible, though other causes still need assessment.'),('A primary psychotic illness established by visual hallucinations','The acute medication relationship and cognitive syndrome favor delirium.'),('A protective effect from combining antimuscarinic drugs','The combination can increase central and peripheral adverse effects.')],
 'Medication review is cause-directed treatment','**Central anticholinergic effects can impair attention and cognition.**',['Older adults and people with cognitive impairment are particularly vulnerable.','Urinary retention and constipation can add further contributors.'],'**Review and reduce offending drugs when clinically feasible.**',['Assess other physiological causes rather than assuming a single culprit.','Monitor cognition, bladder/bowel function and hydration.'],[['Exposure','Additive anticholinergic drugs'],['CNS','Attention/cognitive effects'],['Action','Medication and contributor review']],[DL],style='clinical_scenario')

q('A delirious patient is distressed but not threatening safety. What is the preferred initial symptom-management approach?', 'Reassurance, reorientation, environmental measures and treatment of causes',[
 ('Immediate high-dose haloperidol for every confused patient','Drug treatment is not routine for all delirium.'),('Routine benzodiazepine sedation regardless of cause','This can worsen nonwithdrawal delirium and respiratory risk.'),('Physical restraint as the first response to disorientation','Restraint can increase distress and harm and requires exceptional justification.')],
 'Reduce distress without adding avoidable brain and physical burden','**Nonpharmacological measures are first-line for most delirium symptoms.**',['Identify pain, fear, sensory barriers and unmet needs.','Use familiar people and calm communication.'],'**Reserve short-term medication for specific severe distress or safety situations after assessment.**',['Consider cardiac, neurological and medication risks.','Continue cause treatment and frequent reassessment.'],[['Initial care','Reassurance/environment'],['Underlying problem','Treat contributors'],['Medication','Selected short-term role']],[DL],style='clinical_scenario')

q('An older patient with Lewy body dementia has delirium and agitation. Which issue is especially important before antipsychotic use?', 'Risk of severe antipsychotic sensitivity and worsening parkinsonism',[
 ('All antipsychotics are equally safe in Lewy body disease','Sensitivity and neurological harm can be substantial.'),('Haloperidol is automatically the safest choice because it is potent','Potent dopamine blockade is particularly concerning.'),('The dementia diagnosis removes the need to treat the delirium cause','Reversible contributors still require treatment.')],
 'The same sedative choice can carry very different risks','**Lewy body and Parkinsonian disorders require particular caution with dopamine-blocking drugs.**',['Use nonpharmacological care and cause correction first.','Severe distress or danger requires expert individualized planning.'],'**Review the whole risk-benefit profile.**',['Assess QT risk and interacting medications as well.','Use the lowest appropriate exposure if a specialist-directed drug is necessary.'],[['Neurological risk','Sensitivity/parkinsonism'],['First measures','Cause and environmental care'],['Drug decision','Specialist individualized choice']],[DL,DM],style='clinical_scenario')

q('Which situation is a recognized exception to the general avoidance of routine benzodiazepines for delirium?', 'Alcohol-withdrawal delirium',[
 ('Any new confusion after a urinary catheter is placed','Assess causes and distress rather than automatically giving benzodiazepines.'),('Any dementia-related nighttime wandering','This does not establish a withdrawal indication.'),('Hypoactive delirium without agitation as a reason for sedation','Sedation can worsen assessment and function.')],
 'Delirium treatment depends on the cause','**Withdrawal-related CNS hyperexcitability has a specific benzodiazepine treatment pathway.**',['Sedative withdrawal is another relevant context.','Catatonia is a separate syndrome with a benzodiazepine role.'],'**Do not generalize an exception to all acute confusion.**',['Monitor breathing and sedation during indicated treatment.','Treat metabolic, infectious and other contributors concurrently.'],[['Nonwithdrawal delirium','Avoid routine benzodiazepines'],['Withdrawal delirium','Specific indicated treatment'],['All cases','Cause-directed care']],[DL,ref('ASAM alcohol withdrawal guideline','https://www.asam.org/quality-care/clinical-guidelines/alcohol-withdrawal-management-guideline')])

q('After an episode of delirium, a patient remains below the previous cognitive baseline at discharge. Which plan is appropriate?', 'Document the course, arrange follow-up and reassess for persistent delirium or an underlying neurocognitive disorder',[
 ('Diagnose permanent dementia solely from the discharge score','Recovery may be incomplete and confound testing.'),('Assume no follow-up is needed once infection is treated','Cognitive and functional consequences can persist.'),('Continue any inpatient antipsychotic indefinitely without a new indication','Temporary symptom treatment should be reviewed and stopped when no longer needed.')],
 'Recovery can be slower than resolution of the trigger','**Delirium has important post-discharge cognitive and functional consequences.**',['Communicate baseline, precipitant, treatment and residual problems.','Support caregivers and medication reconciliation.'],'**Reassess over time with appropriate referral.**',['Evaluate safety, falls, nutrition and support needs.','Avoid premature irreversible labels while also not ignoring progressive disease.'],[['Discharge','Document residual impairment'],['Follow-up','Recovery and differential'],['Medication','Review temporary prescriptions']],[DL,DM],style='clinical_scenario')
